// Native, isolated engine verification of campaign economy/production and player bike weapons.
#define Generate_Mission_Starts SAM_Regression
#include "../tests/samblast_engine.cpp"
#undef Generate_Mission_Starts
#include "campaignbike.h"
#include "campaignwaves.h"
static void Prepare(const std::string& dir){Reset(dir);auto e=HouseClass::As_Pointer(HOUSE_BAD);e->IsActive=true;e->IsDefeated=false;e->Credits=200000;e->Tiberium=0;e->Capacity=100000;}
static int EnemyCount(){int n=0;auto add=[&](TechnoClass* a){if(a->IsActive&&!a->IsInLimbo&&a->Strength>0&&a->House==HouseClass::As_Pointer(HOUSE_BAD))++n;};for(int i=0;i<Units.Count();++i)add(Units.Ptr(i));for(int i=0;i<Infantry.Count();++i)add(Infantry.Ptr(i));for(int i=0;i<Aircraft.Count();++i)add(Aircraft.Ptr(i));return n;}
static int Ions(){int n=0;for(int i=0;i<Anims.Count();++i)if(*Anims.Ptr(i)==ANIM_ION_CANNON)++n;return n;}
static void ClearAnims(){for(int i=Anims.Count()-1;i>=0;--i)delete Anims.Ptr(i);}
static void Economy(const std::string& dir){Prepare(dir);auto e=HouseClass::As_Pointer(HOUSE_BAD);e->Credits=0;e->Capacity=10;e->Tiberium=10;int before=e->Available_Money();Campaign_Enemy_Harvest(e,100);Check("enemy real harvest deposit yields ten times credits even with full silos",e->Available_Money()-before==1000);PlayerPtr->Credits=0;PlayerPtr->Tiberium=0;PlayerPtr->Capacity=10000;before=PlayerPtr->Available_Money();Campaign_Enemy_Harvest(PlayerPtr,100);Check("player resource income remains one times",PlayerPtr->Available_Money()-before==100);e->Tiberium=0;e->Capacity=10000;before=e->Available_Money();e->Harvested(100);Check("non-harvest cash/storage paths are not multiplied",e->Available_Money()-before==100);GameToPlay=GAME_SKIRMISH;before=e->Available_Money();Campaign_Enemy_Harvest(e,100);Check("skirmish income remains stock",e->Available_Money()-before==100);GameToPlay=GAME_NORMAL;}
static void NoWaves(const std::string& dir){Prepare(dir);auto p=new UnitClass(UNIT_MTANK,HOUSE_GOOD);Put(p,Center());auto e=new UnitClass(UNIT_LTANK,HOUSE_BAD);Put(e,XY_Cell(Cell_X(Center())+15,Cell_Y(Center())));Campaign_Enemies_Apply();Check("existing initial population retains previous two-times setting",EnemyCount()==2);int before=EnemyCount();for(Frame=1;Frame<=6*60*60*TICKS_PER_SECOND;++Frame){Campaign_Waves_AI();if(EnemyCount()!=before)break;}Check("six hours never creates a timed reinforcement",EnemyCount()==before);Check("save retired wave state",Save_Game((dir+"/old-waves.sav").c_str(),"LEGACY QUEUED WAVES"));{std::ifstream in(dir+"/old-waves.sav",std::ios::binary);std::string b((std::istreambuf_iterator<char>(in)),{});auto pos=b.rfind("CNCWAV02");Check("find old wave footer",pos!=std::string::npos);std::int32_t data[7]={Frame-100,50,30,20,HOUSE_BAD,Center(),-1};if(pos!=std::string::npos){b[pos+7]='1';b.erase(pos+8,4);std::memcpy(&b[pos+8],data,sizeof(data));std::ofstream out(dir+"/old-waves.sav",std::ios::binary|std::ios::trunc);out.write(b.data(),b.size());}}Check("old save with pending reinforcements remains loadable",Load_Game((dir+"/old-waves.sav").c_str()));before=EnemyCount();for(int i=0;i<10000;++i){++Frame;Campaign_Waves_AI();Campaign_Enemies_Apply();if(EnemyCount()!=before)break;}Check("legacy pending wave never resumes spawning",EnemyCount()==before);}
static void Production(const std::string& dir,int kind,bool saveDuring){Prepare(dir);auto e=HouseClass::As_Pointer(HOUSE_BAD);auto factory=new FactoryClass;TechnoTypeClass const* type=kind==0?static_cast<TechnoTypeClass const*>(&UnitTypeClass::As_Reference(UNIT_LTANK)):kind==1?static_cast<TechnoTypeClass const*>(&InfantryTypeClass::As_Reference(INFANTRY_E1)):static_cast<TechnoTypeClass const*>(&AircraftTypeClass::As_Reference(AIRCRAFT_ORCA));int money=e->Available_Money();Check("native enemy factory accepts product",factory->Set(*type,*e)&&factory->Start());int fid=Factories.ID(factory),price=factory->Get_Object()->PurchasePrice;Check("unfinished factory products never spawn companions",EnemyCount()==0);if(saveDuring){for(int i=0;i<10;++i){++Frame;factory->AI();}Check("save queued triple production",Save_Game((dir+"/queue.sav").c_str(),"QUEUED TRIPLE PRODUCTION"));Check("load queued triple production",Load_Game((dir+"/queue.sav").c_str()));factory=Factories.Ptr(fid);e=HouseClass::As_Pointer(HOUSE_BAD);}
 for(int i=0;i<30000&&!factory->Has_Completed();++i){++Frame;factory->AI();}Check("native factory completes by spending its budget",factory->Has_Completed());auto obj=factory->Get_Object();Check("place finished native factory product",obj&&Put(obj,Center()));if(!obj)return;auto oid=obj->As_Target();Check("complete native factory release",factory->Completed());Campaign_Enemies_Apply();std::printf("PRODUCTION kind=%d active=%d spent=%d price=%d\n",kind,EnemyCount(),money-e->Available_Money(),price);Check("one enemy production yields exactly three active units",EnemyCount()==3);Check("only one native product price is paid",money-e->Available_Money()==price);Campaign_Enemies_Apply();Check("tripling never recurses",EnemyCount()==3);Checkpoint(dir);Check("reload never multiplies already tripled units",EnemyCount()==3);auto original=static_cast<FootClass*>(As_Techno(oid));original->Assign_Mission(MISSION_HUNT);original->Commence();Campaign_Enemies_Apply();int follows=0;auto count=[&](FootClass* f){if(!f->IsInLimbo&&f->House==HouseClass::As_Pointer(HOUSE_BAD)&&f->Mission==MISSION_HUNT)++follows;};for(int i=0;i<Units.Count();++i)count(Units.Ptr(i));for(int i=0;i<Infantry.Count();++i)count(Infantry.Ptr(i));for(int i=0;i<Aircraft.Count();++i)count(Aircraft.Ptr(i));Check("both companions follow the original's new orders",follows==3);}
static void PartialProduction(const std::string& dir){Prepare(dir);auto e=HouseClass::As_Pointer(HOUSE_BAD);auto f=new FactoryClass;Check("queue triple production for a nearly full unit heap",f->Set(UnitTypeClass::As_Reference(UNIT_LTANK),*e)&&f->Start());TARGET filler=TARGET_NONE;while(Units.Count()<UNIT_MAX-1){auto u=new UnitClass(UNIT_MTANK,HOUSE_GOOD);if(!u)break;filler=u->As_Target();}for(int tick=0;tick<30000&&!f->Has_Completed();++tick){++Frame;f->AI();}auto obj=f->Get_Object();Check("place product before partial companion allocation",obj&&f->Has_Completed()&&Put(obj,Center()));if(!obj)return;f->Completed();Campaign_Enemies_Apply();Check("only the available companion slot is filled",EnemyCount()==2);Check("save pending third produced unit",Save_Game((dir+"/partial.sav").c_str(),"ONE COMPANION STILL PENDING"));Check("reload pending third produced unit",Load_Game((dir+"/partial.sav").c_str()));Check("full heap never invents or loses a unit during reload",EnemyCount()==2);auto obsolete=As_Unit(filler);if(obsolete)delete obsolete;Campaign_Enemies_Apply();Check("freed slot receives exactly the one missing companion",EnemyCount()==3);Campaign_Enemies_Apply();Check("partial retry never produces a fourth unit",EnemyCount()==3);}
static void Suggest(const std::string& dir){Prepare(dir);for(int i=0;i<TeamTypes.Count();++i)TeamTypes.Ptr(i)->House=HOUSE_NEUTRAL;auto e=HouseClass::As_Pointer(HOUSE_BAD);BuildLevel=99;e->MaxUnit=e->MaxInfantry=100;auto hand=new BuildingClass(STRUCT_HAND,HOUSE_BAD);auto airstrip=new BuildingClass(STRUCT_AIRSTRIP,HOUSE_BAD);Check("place actual enemy barracks and vehicle factory",Put(hand,Center())&&Put(airstrip,XY_Cell(Cell_X(Center())+6,Cell_Y(Center()))));e->ActiveBScan|=STRUCTF_HAND|STRUCTF_AIRSTRIP;e->BScan|=e->ActiveBScan;e->IsStarted=false;e->IsAlerted=false;Campaign_Enemies_Apply();Check("enemy production is started and alerted",e->IsStarted&&e->IsAlerted);auto infantry=e->Suggest_New_Object(RTTI_INFANTRYTYPE);auto unit=e->Suggest_New_Object(RTTI_UNITTYPE);std::printf("SUGGEST infantry=%p vehicle=%p money=%d\n",(void*)infantry,(void*)unit,e->Available_Money());Check("enemy suggests combat infantry without scripted team demand",infantry&&infantry->Primary!=WEAPON_NONE);Check("enemy without a construction yard first requests an expansion MCV",unit==&UnitTypeClass::As_Reference(UNIT_MCV));auto pendingMCV=new UnitClass(UNIT_MCV,HOUSE_BAD);unit=e->Suggest_New_Object(RTTI_UNITTYPE);Check("enemy suggests combat vehicles while an expansion MCV is already pending",unit&&unit->Primary!=WEAPON_NONE);e->Credits=0;e->Tiberium=0;Check("aggressive production still requires money",!e->Suggest_New_Object(RTTI_INFANTRYTYPE));}
static void Autonomous(const std::string& dir){
 Prepare(dir);for(int i=0;i<TeamTypes.Count();++i)TeamTypes.Ptr(i)->House=HOUSE_NEUTRAL;auto e=HouseClass::As_Pointer(HOUSE_BAD);BuildLevel=99;e->MaxInfantry=100;auto hand=new BuildingClass(STRUCT_HAND,HOUSE_BAD);Check("place autonomous enemy barracks",Put(hand,Center()));++ScenarioInit;hand->Begin_Mode(BSTATE_IDLE);--ScenarioInit;hand->Assign_Mission(MISSION_GUARD);hand->Commence();e->ActiveBScan|=STRUCTF_HAND;e->BScan|=STRUCTF_HAND;Campaign_Enemies_Apply();int money=e->Available_Money();
 for(int tick=0;tick<20000&&EnemyCount()<6;++tick){++Frame;std::vector<FactoryClass*> entries;for(int i=0;i<Factories.Count();++i)entries.push_back(Factories.Ptr(i));for(auto factory:entries)factory->AI();hand->AI();std::vector<TARGET> infantry;for(int i=0;i<Infantry.Count();++i)if(!Infantry.Ptr(i)->IsInLimbo)infantry.push_back(Infantry.Ptr(i)->As_Target());for(auto id:infantry){auto a=As_Infantry(id);if(a)a->AI();}Campaign_Enemies_Apply();}
 std::printf("AUTONOMOUS active=%d spent=%d\n",EnemyCount(),money-e->Available_Money());Check("actual barracks AI continuously purchases and releases triple batches",EnemyCount()>=6&&e->Available_Money()<money);
}
static UnitClass* Bike(const std::string& dir,bool own=true){Prepare(dir);ClearAnims();auto b=new UnitClass(UNIT_BIKE,own?HOUSE_GOOD:HOUSE_BAD);Check("place attack bike",Put(b,Center()));b->Assign_Mission(MISSION_SLEEP);b->Commence();return b;}
static UnitClass* Victim(UnitClass* bike,int x,int y=0){auto t=new UnitClass(UNIT_MTANK,HOUSE_BAD);Check("place ion target",Put(t,Coord_Cell(XY_Coord(Coord_X(bike->Coord)+x*ICON_LEPTON_W,Coord_Y(bike->Coord)+y*ICON_LEPTON_W))));t->Strength=30000;t->IsDiscoveredByPlayer=true;Campaign_Enemies_Mark_Extra(t);return t;}
static void Missile(const std::string& dir){auto b=Bike(dir);auto t=Victim(b,3);auto shot=b->TechnoClass::Fire_At(t->As_Target(),0);Check("player bike launches original SAM projectile shape and strength",shot&&*shot==BULLET_SAM&&shot->Strength==50);Check("bike missile uses original full SAM flight speed",shot&&shot->Get_Speed()==Fixed_To_Cardinal((int)shot->Class->MaxSpeed,255));Check("bike missile does not acquire SAM-site ricochets",shot&&!Campaign_SAM_Chain_Impact(shot,t));int original=(int)Weapons[WEAPON_DRAGON].ROF*b->House->ROFBias+3;Check("bike reload is half its original delay",b->Rearm_Delay(true)==MAX(1,original/2));b=Bike(dir,false);t=Victim(b,3);shot=b->TechnoClass::Fire_At(t->As_Target(),0);Check("enemy bike missile remains original Dragon weapon",shot&&*shot==BULLET_TOW&&shot->Strength==30);}
static void NativeMissile(const std::string& dir){auto b=Bike(dir);auto t=Victim(b,3);b->PrimaryFacing=DIR_E;b->Assign_Target(TARGET_NONE);b->Assign_Mission(MISSION_GUARD);b->Commence();bool launched=false;for(int tick=0;tick<300&&!launched;++tick){++Frame;b->AI();launched=Bullets.Count()>0;}Check("native bike guard AI actually launches the SAM-shaped missile",launched&&*Bullets.Ptr(0)==BULLET_SAM);for(int tick=0;tick<300&&Bullets.Count();++tick)TickBullets();Check("native bike missile flight actually damages its target",t->Strength<30000);}
static void IonFilters(const std::string& dir){auto b=Bike(dir);auto t=Victim(b,7);t->IsDiscoveredByPlayer=false;Campaign_Bike_AI(b);Check("orbital attack does not reveal hidden ground units",Ions()==0);Frame+=15;t->IsDiscoveredByPlayer=true;t->Cloak=CLOAKED;Campaign_Bike_AI(b);Check("orbital attack excludes cloaked enemies",Ions()==0);Frame+=15;t->Cloak=UNCLOAKED;t->House=PlayerPtr;Campaign_Bike_AI(b);Check("orbital attack excludes friendly units",Ions()==0);Frame+=15;t->House=HouseClass::As_Pointer(HOUSE_NEUTRAL);Campaign_Bike_AI(b);Check("orbital attack excludes neutral units",Ions()==0);Frame+=15;t->House=HouseClass::As_Pointer(HOUSE_BAD);Campaign_Bike_AI(b);Check("orbital attack resumes for a visible hostile",Ions()==1);
 b=Bike(dir);auto a=new AircraftClass(AIRCRAFT_ORCA,HOUSE_BAD);a->Altitude=AircraftClass::FLIGHT_LEVEL;Check("place airborne orbital target",Put(a,Coord_Cell(XY_Coord(Coord_X(b->Coord)+7*ICON_LEPTON_W,Coord_Y(b->Coord)))));a->Strength=30000;a->IsDiscoveredByPlayer=true;Campaign_Bike_AI(b);Check("orbital attack also damages airborne enemies",Ions()==1&&a->Strength<30000);
}
static void IonCadence(const std::string& dir){auto b=Bike(dir);Victim(b,7,-1);Victim(b,7,1);int start=Frame;for(int tick=0;tick<=45;++tick){Frame=start+tick;b->AI();Check("native bike AI casts one ion per game second",Ions()==1+tick/TICKS_PER_SECOND);}for(int strike=4;strike<32;++strike){Frame=start+strike*TICKS_PER_SECOND;b->AI();Check("one ion strike per elapsed second remains stable over thirty-two shots",Ions()==strike+1);}std::set<COORDINATE> points;for(int i=0;i<Anims.Count();++i)if(*Anims.Ptr(i)==ANIM_ION_CANNON)points.insert(Anims.Ptr(i)->Coord);Check("ion strikes randomly choose more than one enemy",points.size()>1);}
static void IonBoundary(const std::string& dir){auto b=Bike(dir);auto t=Victim(b,10);t->Coord=XY_Coord(Coord_X(b->Coord)+10*ICON_LEPTON_W+1,Coord_Y(b->Coord));Campaign_Bike_AI(b);Check("ion excludes targets one lepton outside ten cells",Ions()==0);t->Coord=XY_Coord(Coord_X(b->Coord)+10*ICON_LEPTON_W,Coord_Y(b->Coord));Frame+=15;Campaign_Bike_AI(b);Check("ion includes targets exactly ten cells away",Ions()==1);}
static void IonSave(const std::string& dir){auto b=Bike(dir);Victim(b,7);auto bid=b->As_Target();Campaign_Bike_AI(b);Frame+=7;Check("save partially elapsed ion cooldown",Save_Game((dir+"/ion.sav").c_str(),"ION COOLDOWN"));Check("reload partially elapsed ion cooldown",Load_Game((dir+"/ion.sav").c_str()));b=static_cast<UnitClass*>(As_Techno(bid));int before=Ions();Campaign_Bike_AI(b);Check("reload does not grant a free ion strike",Ions()==before);Frame+=7;Campaign_Bike_AI(b);Check("ion cooldown still waits its saved remaining interval",Ions()==before);++Frame;Campaign_Bike_AI(b);Check("ion fires exactly when saved cooldown expires",Ions()==before+1);}
static void IonDamage(const std::string& dir){auto b=Bike(dir);auto t=Victim(b,7);Campaign_Bike_AI(b);for(int tick=0;tick<400&&Ions();++tick){++Frame;std::vector<TARGET> ids;for(int i=0;i<Anims.Count();++i)ids.push_back(Anims.Ptr(i)->As_Target());for(auto id:ids){auto a=As_Animation(id);if(a)a->AI();}}std::printf("ION DAMAGE %d\n",30000-t->Strength);Check("original ion animation really applies its native 600-power strike",t->Strength<30000);Check("bike outside blast survives its orbital strike",b->IsActive&&b->Strength>0);b=Bike(dir,false);Victim(b,7);Campaign_Bike_AI(b);Check("enemy bikes do not gain orbital strikes",Ions()==0);b=Bike(dir);Victim(b,7);GameToPlay=GAME_SKIRMISH;Campaign_Bike_AI(b);Check("skirmish bikes remain unchanged",Ions()==0);GameToPlay=GAME_NORMAL;}
bool Generate_Mission_Starts(const char* directory){std::string dir(directory);Economy(dir);NoWaves(dir);for(int k=0;k<3;++k)Production(dir,k,k==0);PartialProduction(dir);Suggest(dir);Autonomous(dir);Missile(dir);NativeMissile(dir);IonFilters(dir);IonCadence(dir);IonBoundary(dir);IonSave(dir);IonDamage(dir);std::printf("TOTAL FAILURES %d\n",failures);return failures==0;}
